import type { Lang } from '@/lib/supabase/types'

export type POS = 'v' | 'n' | 'a' | 'x'

export interface Word {
  id: string         // w001..w440
  pos: POS
  fr: string
  en: string
  de: string
  es: string
  it: string
  catId: string      // '1'..'9'
  subId: string      // '1.1'..'9.3'
}

/** Parse slash variants: "un/le chat" → ['un chat', 'le chat'] */
export function parseVariants(field: string): string[] {
  if (!field.includes('/')) return [field]
  const parts = field.split('/')
  // If it looks like "word1/word2" return both
  return parts.map(p => p.trim()).filter(Boolean)
}

/** Pick random variant for quiz article randomization */
export function randomVariant(field: string): string {
  const v = parseVariants(field)
  return v[Math.floor(Math.random() * v.length)]
}

