// Lookup map for O(1) access
export const WORD_MAP = new Map<string, Word>(WORDS.map(w => [w.id, w]))

/** Words by subcategory */
export function getWordsBySub(subId: string): Word[] {
  return WORDS.filter(w => w.subId === subId)
}

/** Words by category */
export function getWordsByCat(catId: string): Word[] {
  return WORDS.filter(w => w.catId === catId)
}

/** Get target-lang field */
export function getTargetField(word: Word, lang: Lang): string {
  return word[lang]
}

